    /// <summary>
    /// Escolhe a silhueta pela sigla da posição (GOL, LAT, ZAG, MEI, ATA, TEC; MC vale MEI).
    /// O modelo 1 ou 2 é decidido pelo nome, então o mesmo atleta sempre recebe a mesma figura.
    /// </summary>
    public static string Caminho(string? sigla, string? nome)
    {
        var s = (sigla ?? "").Trim().ToUpperInvariant();
        if (s == "MC") s = "MEI";
        if (s == "TEC") return Mapa["TEC"];
        if (s is not ("GOL" or "LAT" or "ZAG" or "MEI" or "ATA")) s = "MEI";
        uint h = 17;
        foreach (var c in nome ?? "") h = unchecked(h * 31 + c);
        return Mapa[s + (h % 2 == 0 ? "1" : "2")];
    }
}
